namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Deck of Illusions (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class DeckOfIllusions2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("deck-of-illusions", null, 0, MagicItemType.WondrousItem, ItemRarity.Uncommon, false, ContentSource.Srd51,
			null,
			("Mazzo delle illusioni", "Oggetto meraviglioso, non comune",
			"Questa scatola contiene un mazzo di carte pergamenate. Un mazzo completo è composto da 34 carte. In un mazzo trovato come tesoro solitamente mancano 1d20 – 1 carte.\n\nLa magia del mazzo funziona solo se le carte vengono pescate casualmente (è possibile usare un normale mazzo di carte opportunamente modificato per simulare quest'oggetto magico). Il personaggio può usare un'azione per pescare una carta casuale dal mazzo e gettarla a terra in un punto entro 9 metri da sé.\n\nDalla carta gettata a terra si genera un'illusione raffigurante una o più creature che permangono finché non vengono dissolte. Le creature illusorie appaiono reali, hanno la taglia giusta e si comportano esattamente come le creature che simulano, ma non possono nuocere in alcun modo. Finché il personaggio resta entro 36 metri dalla creatura illusoria ed è in grado di vederla, può usare un'azione per spostarla magicamente fino a un qualsiasi punto entro 9 metri dalla sua carta. Ogni interazione fisica con la creatura illusoria rivela che si tratta di un'illusione, in quanto gli oggetti passano attraverso di essa. Chi usa un'azione per esaminare visivamente la creatura, la identifica come illusoria effettuando con successo una prova di Intelligenza (Indagare) con CD 15. In questo caso la creatura appare trasparente all'osservatore.\n\nL'illusione dura finché la carta non viene spostata o l'illusione non viene dissolta. Quando l'illusione termina, l'immagine raffigurata sulla sua carta scompare e la carta non può più essere utilizzata.\n\n| Carta da gioco | Illusione |\n|---|---|\n| Asso di cuori | Drago rosso |\n| Re di cuori | Cavaliere e quattro guardie |\n| Regina di cuori | Succube o incubo |\n| Jack di cuori | Druido |\n| Dieci di cuori | Giganti delle nuvole |\n| Nove di cuori | Ettin |\n| Otto di cuori | Bugbear |\n| Due di cuori | Goblin |\n| Asso di quadri | Beholder |\n| Re di quadri | Arcimago e apprendista mago |\n| Regina di quadri | Megera notturna |\n| Jack di quadri | Assassino |\n| Dieci di quadri | Gigante del fuoco |\n| Nove di quadri | Ogre mago |\n| Otto di quadri | Gnoll |\n| Due di quadri | Coboldo |\n| Asso di spade | Lich |\n| Re di picche | Sacerdote e due accoliti |\n| Regina di picche | Medusa |\n| Jack di picche | Veterano |\n| Dieci di picche | Gigante del gelo |\n| Nove di picche | Troll |\n| Otto di picche | Hobgoblin |\n| Due di picche | Goblin |\n| Asso di fiori | Golem di ferro |\n| Re di fiori | Capitano bandito e tre banditi |\n| Regina di fiori | Erinni |\n| Jack di fiori | Berserker |\n| Dieci di fiori | Gigante delle colline |\n| Nove di fiori | Ogre |\n| Otto di fiori | Orco |\n| Due di fiori | Coboldo |\n| Jolly (2) | Il personaggio (il proprietario del mazzo) |", null),
			("Deck of Illusions", "Wondrous item, uncommon",
			"This box contains a set of parchment cards. A full deck has 34 cards. A deck found as treasure is usually missing 1d20 - 1 cards.\n\nThe magic of the deck functions only if cards are drawn at random (you can use an altered deck of playing cards to simulate the deck). You can use an action to draw a card at random from the deck and throw it to the ground at a point within 30 feet of you.\n\nAn illusion of one or more creatures forms over the thrown card and remains until dispelled. An illusory creature appears real, of the appropriate size, and behaves as if it were a real creature except that it can do no harm. While you are within 120 feet of the illusory creature and can see it, you can use an action to move it magically anywhere within 30 feet of its card. Any physical interaction with the illusory creature reveals it to be an illusion, because objects pass through it. Someone who uses an action to visually inspect the creature identifies it as illusory with a successful DC 15 Intelligence (Investigation) check. The creature then appears translucent.\n\nThe illusion lasts until its card is moved or the illusion is dispelled. When the illusion ends, the image on its card disappears, and that card can't be used again.\n\n| Playing Card | Illusion |\n|---|---|\n| Ace of hearts | Red dragon |\n| King of hearts | Knight and four guards |\n| Queen of hearts | Succubus or incubus |\n| Jack of hearts | Druid |\n| Ten of hearts | Cloud giant |\n| Nine of hearts | Ettin |\n| Eight of hearts | Bugbear |\n| Two of hearts | Goblin |\n| Ace of diamonds | Beholder |\n| King of diamonds | Archmage and mage apprentice |\n| Queen of diamonds | Night hag |\n| Jack of diamonds | Assassin |\n| Ten of diamonds | Fire giant |\n| Nine of diamonds | Ogre mage |\n| Eight of diamonds | Gnoll |\n| Two of diamonds | Kobold |\n| Ace of spades | Lich |\n| King of spades | Priest and two acolytes |\n| Queen of spades | Medusa |\n| Jack of spades | Veteran |\n| Ten of spades | Frost giant |\n| Nine of spades | Troll |\n| Eight of spades | Hobgoblin |\n| Two of spades | Goblin |\n| Ace of clubs | Iron golem |\n| King of clubs | Bandit captain and three bandits |\n| Queen of clubs | Erinyes |\n| Jack of clubs | Berserker |\n| Ten of clubs | Hill giant |\n| Nine of clubs | Ogre |\n| Eight of clubs | Orc |\n| Two of clubs | Kobold |\n| Jokers (2) | You (the deck's owner) |", null));
	}
